/// <reference path="../_external/.onlinestream-provider.d.ts" />
/// <reference path="../_external/core.d.ts" />

//#region config

const VIDBOX_BASE = "https://vidbox.dev";
const SEANIME_API = "http://127.0.0.1:43211/api/v1/proxy?url=";

// vidbox.dev URL structure (TMDB-based):
//   Page anime/TV  : /tv/{tmdbId}
//   Page film      : /movie/{tmdbId}
//   Embed TV ep    : /embed/tv/{tmdbId}/{season}/{episode}
//   Embed film     : /embed/movie/{tmdbId}

//#endregion

//#region helpers

function isMovie(format: string): boolean {
    return format === "MOVIE" || format === "OVA" || format === "SPECIAL";
}

//#endregion

class Provider {

    getSettings(): Settings {
        return {
            // vidbox.dev aggregates multiple servers internally;
            // we expose them as separate selectable servers in Seanime.
            episodeServers: [
                "vidbox",
                "vidbox-fr",
                "vidbox-en",
                "vidbox-vostfr",
            ],
            supportsDub: true,
        };
    }

    //#region URL builders

    private buildPageUrl(tmdbId: string, format: string): string {
        return isMovie(format)
            ? `${VIDBOX_BASE}/movie/${tmdbId}`
            : `${VIDBOX_BASE}/tv/${tmdbId}`;
    }

    private buildEmbedUrl(tmdbId: string, format: string, season?: number, episode?: number): string {
        if (isMovie(format)) {
            return `${VIDBOX_BASE}/embed/movie/${tmdbId}`;
        }
        return `${VIDBOX_BASE}/embed/tv/${tmdbId}/${season ?? 1}/${episode ?? 1}`;
    }

    //#endregion

    //#region search

    async search(opts: SearchOptions): Promise<SearchResult[]> {
        // vidbox.dev is TMDB-based: resolve via TMDB ID if available,
        // otherwise fall back to a title search on the vidbox.dev search page.
        const tmdbId = opts.media.tmdbId?.toString();
        const format = opts.media.format ?? "TV";

        if (tmdbId) {
            const pageUrl = this.buildPageUrl(tmdbId, format);
            console.log(`[VidBox] Resolved via TMDB ID ${tmdbId} -> ${pageUrl}`);
            return [{
                id: `${tmdbId}::${format}`,
                title: opts.query,
                url: pageUrl,
                subOrDub: opts.dub ? "dub" : "sub",
            }];
        }

        // Fallback: search by title on vidbox.dev
        console.log(`[VidBox] No TMDB ID, searching by title: "${opts.query}"`);
        try {
            const searchUrl = `${VIDBOX_BASE}/search/${encodeURIComponent(opts.query)}`;
            const html = await fetch(`${SEANIME_API}${encodeURIComponent(searchUrl)}`).then(r => r.text());

            const nextDataMatch = html.match(/<script id="__NEXT_DATA__" type="application\/json">(.*?)<\/script>/);
            if (!nextDataMatch) {
                console.warn("[VidBox] Could not find __NEXT_DATA__ in search page");
                return [];
            }

            const data = JSON.parse(nextDataMatch[1]);
            const results: any[] = data?.props?.pageProps?.results ?? [];

            if (results.length === 0) {
                console.warn("[VidBox] No search results found for:", opts.query);
                return [];
            }

            // Pick the best matching result by title similarity
            const queryLower = opts.query.toLowerCase();
            const scored = results.map((r: any) => {
                const title: string = (r.name ?? r.title ?? r.original_name ?? "").toLowerCase();
                const mediaType: string = r.media_type ?? (isMovie(format) ? "movie" : "tv");
                let score = 0;
                if (title === queryLower) score += 10;
                else if (title.includes(queryLower)) score += 5;
                // Prefer correct media type
                if ((isMovie(format) && mediaType === "movie") || (!isMovie(format) && mediaType === "tv")) score += 3;
                return { r, score };
            });

            scored.sort((a, b) => b.score - a.score);
            const best = scored[0].r;
            const bestId: string = best.id?.toString() ?? "";
            const bestType: string = best.media_type ?? (isMovie(format) ? "movie" : "tv");
            const bestPageUrl = `${VIDBOX_BASE}/${bestType}/${bestId}`;
            const bestFormat = bestType === "movie" ? "MOVIE" : "TV";

            console.log(`[VidBox] Best search match: "${best.name ?? best.title}" -> ${bestPageUrl}`);

            return [{
                id: `${bestId}::${bestFormat}`,
                title: best.name ?? best.title ?? opts.query,
                url: bestPageUrl,
                subOrDub: opts.dub ? "dub" : "sub",
            }];
        } catch (e) {
            console.error("[VidBox] Search fallback failed:", e);
            return [];
        }
    }

    //#endregion

    //#region episodes

    async findEpisodes(id: string): Promise<EpisodeDetails[]> {
        const parts = id.split("::");
        const tmdbId = parts[0];
        const format = parts[1] ?? "TV";
        const results: EpisodeDetails[] = [];

        // --- MOVIE / OVA / SPECIAL: single entry ---
        if (isMovie(format)) {
            results.push({
                id: `${tmdbId}::${format}::1::1`,
                url: this.buildEmbedUrl(tmdbId, format),
                number: 1,
            });
            return results;
        }

        // --- TV / ANIME: parse seasons & episodes from vidbox.dev page ---
        try {
            const pageUrl = `${VIDBOX_BASE}/tv/${tmdbId}`;
            const html = await fetch(`${SEANIME_API}${encodeURIComponent(pageUrl)}`).then(r => r.text());

            const nextDataMatch = html.match(/<script id="__NEXT_DATA__" type="application\/json">(.*?)<\/script>/);
            if (nextDataMatch) {
                const data = JSON.parse(nextDataMatch[1]);
                const pageProps = data?.props?.pageProps ?? {};

                // vidbox.dev may store seasons under different keys
                const seasons: any[] =
                    pageProps?.seasons ??
                    pageProps?.details?.seasons ??
                    pageProps?.tvDetails?.seasons ??
                    pageProps?.data?.seasons ??
                    [];

                if (seasons.length > 0) {
                    for (const season of seasons) {
                        const seasonNum: number = season.season_number ?? season.seasonNumber ?? 1;
                        if (seasonNum === 0) continue; // skip specials season
                        const episodeCount: number = season.episode_count ?? season.episodeCount ?? 0;

                        for (let ep = 1; ep <= episodeCount; ep++) {
                            results.push({
                                id: `${tmdbId}::TV::${seasonNum}::${ep}`,
                                url: this.buildEmbedUrl(tmdbId, "TV", seasonNum, ep),
                                number: ep,
                            });
                        }
                    }

                    if (results.length > 0) {
                        console.log(`[VidBox] Found ${results.length} episodes across ${seasons.length} season(s) for TMDB ${tmdbId}`);
                        return results;
                    }
                }

                // Some pages list episodes directly (single-season shows)
                const episodes: any[] =
                    pageProps?.episodes ??
                    pageProps?.details?.episodes ??
                    [];

                if (episodes.length > 0) {
                    for (const ep of episodes) {
                        const epNum: number = ep.episode_number ?? ep.episodeNumber ?? ep.number ?? 0;
                        if (epNum === 0) continue;
                        const seasonNum: number = ep.season_number ?? ep.seasonNumber ?? 1;
                        results.push({
                            id: `${tmdbId}::TV::${seasonNum}::${epNum}`,
                            url: this.buildEmbedUrl(tmdbId, "TV", seasonNum, epNum),
                            number: epNum,
                        });
                    }

                    if (results.length > 0) {
                        console.log(`[VidBox] Found ${results.length} episodes (flat list) for TMDB ${tmdbId}`);
                        return results;
                    }
                }
            }
        } catch (e) {
            console.warn("[VidBox] Failed to parse episode list from page:", e);
        }

        // Fallback: expose at least episode 1 so the user can start watching
        console.warn(`[VidBox] Could not determine episode list for TMDB ${tmdbId}, defaulting to ep 1`);
        results.push({
            id: `${tmdbId}::TV::1::1`,
            url: this.buildEmbedUrl(tmdbId, "TV", 1, 1),
            number: 1,
        });

        return results;
    }

    //#endregion

    //#region server

    async findEpisodeServer(episode: EpisodeDetails, server: string): Promise<EpisodeServer> {
        const embedUrl = episode.url;
        console.log(`[VidBox] Server "${server}" -> embed: ${embedUrl}`);

        return {
            headers: {
                referer: VIDBOX_BASE + "/",
                origin: VIDBOX_BASE,
            },
            server: server,
            videoSources: [{
                url: embedUrl,
                quality: "auto",
                type: "iframe",
                subtitles: [],
            }],
        };
    }

    //#endregion
}
